/**
 * Generates src/lib/icons.ts.
 *
 * Brand glyphs come from `simple-icons` (CC0-1.0), pinned into a generated file
 * so the site ships no icon dependency at runtime and the paths cannot shift
 * under us on an unrelated `npm install`.
 *
 * simple-icons has no LinkedIn (removed over trademark policy) and no Luma, so
 * those two — plus a generic website globe — are neutral outline icons drawn
 * here rather than reproductions of marks the upstream set deliberately omits.
 *
 * Run with: node scripts/generate-icons.mjs
 */
import { writeFile } from "node:fs/promises"
import path from "node:path"
import { fileURLToPath } from "node:url"
import * as simpleIcons from "simple-icons"

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..")
const OUT = path.join(root, "src/lib/icons.ts")

/** name -> simple-icons export */
const BRAND = {
  github: "siGithub",
  x: "siX",
  instagram: "siInstagram",
  youtube: "siYoutube",
  discord: "siDiscord",
  whatsapp: "siWhatsapp",
  // NB: no `cal` here. simple-icons ships Cal.com as a full wordmark, which is
  // an illegible smudge at the 16px these render at. Drawn as a glyph below.
}

/** Stroked, 24x24, drawn to sit at the same optical weight as the filled set. */
const OUTLINE = {
  website: [
    "M12 21a9 9 0 1 1 0-18 9 9 0 0 1 0 18Z",
    "M3.5 9.5h17",
    "M3.5 14.5h17",
    "M12 3c2.5 2.6 3.75 5.6 3.75 9S14.5 18.4 12 21C9.5 18.4 8.25 15.4 8.25 12S9.5 5.6 12 3Z",
  ].join(" "),
  linkedin: ["M12 12.5a4.25 4.25 0 1 0 0-8.5 4.25 4.25 0 0 0 0 8.5Z", "M4.5 20.5a7.5 7.5 0 0 1 15 0"].join(" "),
  // Booking a slot: a calendar that has been ticked.
  cal: ["M4.5 6.5h15v13h-15z", "M4.5 10.5h15", "M8.5 3.5v4", "M15.5 3.5v4", "M9 14.75l2 2 4-4"].join(" "),
  // Luma is events, so a ticket - and it must not read as the calendar above.
  luma: [
    "M4 9.6V7.5a1 1 0 0 1 1-1h14a1 1 0 0 1 1 1v2.1a2.4 2.4 0 0 0 0 4.8v2.1a1 1 0 0 1-1 1H5a1 1 0 0 1-1-1v-2.1a2.4 2.4 0 0 0 0-4.8Z",
    "M14 7v10",
  ].join(" "),
  link: [
    "M10.5 13.5a3.75 3.75 0 0 0 5.3 0l2.8-2.8a3.75 3.75 0 0 0-5.3-5.3l-1.4 1.4",
    "M13.5 10.5a3.75 3.75 0 0 0-5.3 0l-2.8 2.8a3.75 3.75 0 0 0 5.3 5.3l1.4-1.4",
  ].join(" "),
}

const entries = []

for (const [name, exportName] of Object.entries(BRAND)) {
  const icon = simpleIcons[exportName]
  if (!icon) throw new Error(`simple-icons has no export ${exportName} (for "${name}")`)
  entries.push({ name, path: icon.path, filled: true, credit: icon.title })
}

for (const [name, d] of Object.entries(OUTLINE)) {
  entries.push({ name, path: d, filled: false, credit: null })
}

const body = `// GENERATED by scripts/generate-icons.mjs - do not edit by hand.
//
// Brand glyphs (filled) are from simple-icons, licensed CC0-1.0.
// Outline glyphs are drawn in that script; simple-icons carries no LinkedIn
// (trademark policy) and no Luma.

export type IconName = ${entries.map((entry) => `"${entry.name}"`).join(" | ")}

export type Icon = { path: string; filled: boolean }

export const icons: Record<IconName, Icon> = {
${entries
  .map((entry) => `  ${entry.name}: {\n    path: "${entry.path}",\n    filled: ${entry.filled},\n  },`)
  .join("\n")}
}

/** Socials are keyed by the label crafter.run publishes. */
export const SOCIAL_ICONS: Record<string, IconName> = {
  GitHub: "github",
  X: "x",
  Instagram: "instagram",
  YouTube: "youtube",
  Discord: "discord",
  WhatsApp: "whatsapp",
  Luma: "luma",
  Research: "link",
  LinkedIn: "linkedin",
}

export function iconForSocial(label: string): IconName {
  return SOCIAL_ICONS[label] ?? "link"
}
`

await writeFile(OUT, body)
console.log(`wrote ${path.relative(root, OUT)} (${entries.length} icons: ${entries.map((e) => e.name).join(", ")})`)
